/**
 * SYNTHETIC test photos for the AquaScan site-photo workflow (2026-11-25). Every image and
 * EXIF block here is generated by code: none is a real photograph of any site.
 */
import { deflateSync } from 'node:zlib';
import type { RgbaImage } from '@/external/borehole-ai-engine/src/sitePhotoChecks';

/** Deterministic textured "outdoor" image: noise plus gradients (sharp edges everywhere). */
export function sharpImage(w = 1200, h = 900, seed = 1): RgbaImage {
  const data = new Uint8ClampedArray(w * h * 4);
  let s = seed;
  const rnd = () => { s = (s * 1103515245 + 12345) % 2147483648; return s / 2147483648; };
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = (y * w + x) * 4;
    const block = ((Math.floor(x / (24 + seed)) + Math.floor(y / (18 + seed))) % 2) * 60;
    const v = 60 + block + rnd() * 80;
    data[i] = v; data[i + 1] = v * 0.9 + 10 * seed; data[i + 2] = v * 0.7; data[i + 3] = 255;
  }
  return { width: w, height: h, data };
}

/** Heavy box blur of an image (radius r), separable. */
export function blurred(img: RgbaImage, r = 12): RgbaImage {
  const { width: w, height: h } = img;
  const pass = (src: Uint8ClampedArray | Uint8Array, horiz: boolean) => {
    const out = new Uint8ClampedArray(src.length);
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) for (let c = 0; c < 4; c++) {
      let sum = 0, n = 0;
      for (let k = -r; k <= r; k++) {
        const xx = horiz ? Math.min(w - 1, Math.max(0, x + k)) : x, yy = horiz ? y : Math.min(h - 1, Math.max(0, y + k));
        sum += src[(yy * w + xx) * 4 + c]; n++;
      }
      out[(y * w + x) * 4 + c] = sum / n;
    }
    return out;
  };
  return { width: w, height: h, data: pass(pass(img.data, true), false) };
}

export function scaled(img: RgbaImage, f: number, add = 0): RgbaImage {
  const d = new Uint8ClampedArray(img.data.length);
  for (let i = 0; i < d.length; i++) d[i] = (i % 4 === 3) ? 255 : img.data[i] * f + add;
  return { width: img.width, height: img.height, data: d };
}

// ── minimal JPEG with an EXIF block (little-endian TIFF) ──
export function jpegWithExif(opts: { lat?: number; lon?: number; date?: string; make?: string } = {}): Uint8Array {
  const tiff: number[] = [];
  const u16 = (v: number) => [v & 255, (v >> 8) & 255];
  const u32 = (v: number) => [v & 255, (v >> 8) & 255, (v >> 16) & 255, (v >>> 24) & 255];
  const make = (opts.make ?? 'SyntheticCam') + '\0';
  const date = (opts.date ?? '2026:11:20 10:15:00') + '\0';
  const hasGps = opts.lat != null && opts.lon != null;
  const ifd0Count = hasGps ? 3 : 2;
  const ifd0 = 8, ifd0End = ifd0 + 2 + ifd0Count * 12 + 4;
  const makeOff = ifd0End, exifIfd = makeOff + make.length, exifEnd = exifIfd + 18, dateOff = exifEnd, gpsIfd = dateOff + date.length;
  const gpsEnd = gpsIfd + 2 + 4 * 12 + 4, latOff = gpsEnd, lonOff = latOff + 24;
  const entry = (tag: number, type: number, count: number, value: number[]) => [...u16(tag), ...u16(type), ...u32(count), ...value];
  tiff.push(0x49, 0x49, ...u16(42), ...u32(8));
  tiff.push(...u16(ifd0Count), ...entry(0x010f, 2, make.length, u32(makeOff)), ...entry(0x8769, 4, 1, u32(exifIfd)));
  if (hasGps) tiff.push(...entry(0x8825, 4, 1, u32(gpsIfd)));
  tiff.push(...u32(0));
  for (const ch of make) tiff.push(ch.charCodeAt(0));
  tiff.push(...u16(1), ...entry(0x9003, 2, date.length, u32(dateOff)), ...u32(0));
  for (const ch of date) tiff.push(ch.charCodeAt(0));
  if (hasGps) {
    const dms = (v: number) => { const a = Math.abs(v); const d = Math.floor(a), m = Math.floor((a - d) * 60), s = Math.round(((a - d) * 60 - m) * 60 * 10000); return [d, 1, m, 1, s, 10000]; };
    tiff.push(...u16(4),
      ...entry(1, 2, 2, [(opts.lat as number) < 0 ? 83 : 78, 0, 0, 0]), ...entry(2, 5, 3, u32(latOff)),
      ...entry(3, 2, 2, [(opts.lon as number) < 0 ? 87 : 69, 0, 0, 0]), ...entry(4, 5, 3, u32(lonOff)), ...u32(0));
    for (const v of dms(opts.lat as number)) tiff.push(...u32(v));
    for (const v of dms(opts.lon as number)) tiff.push(...u32(v));
  }
  const app1 = [0x45, 0x78, 0x69, 0x66, 0, 0, ...tiff];
  const len = app1.length + 2;
  return new Uint8Array([0xff, 0xd8, 0xff, 0xe1, (len >> 8) & 255, len & 255, ...app1, 0xff, 0xd9]);
}

// ── tiny real PNG (for embedding in the generated reports) ──
const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = (b: Uint8Array) => { let c = 0xffffffff; for (const x of b) c = crcTable[(c ^ x) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
export function pngDataUrl(w = 16, h = 12, rgb: [number, number, number] = [90, 140, 60]): string {
  const raw = new Uint8Array(h * (1 + w * 3));
  for (let y = 0; y < h; y++) { raw[y * (1 + w * 3)] = 0; for (let x = 0; x < w; x++) raw.set(rgb.map((v) => (v + x * 5 + y * 3) & 255), y * (1 + w * 3) + 1 + x * 3); }
  const chunk = (type: string, data: Uint8Array) => {
    const t = new Uint8Array([...type].map((c) => c.charCodeAt(0)));
    const body = new Uint8Array(t.length + data.length); body.set(t); body.set(data, t.length);
    const out = new Uint8Array(12 + data.length);
    new DataView(out.buffer).setUint32(0, data.length); out.set(body, 4); new DataView(out.buffer).setUint32(8 + data.length, crc32(body));
    return out;
  };
  const ihdr = new Uint8Array(13); const dv = new DataView(ihdr.buffer); dv.setUint32(0, w); dv.setUint32(4, h); ihdr.set([8, 2, 0, 0, 0], 8);
  const parts = [new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', new Uint8Array(deflateSync(raw))), chunk('IEND', new Uint8Array(0))];
  const all = new Uint8Array(parts.reduce((a, p) => a + p.length, 0)); let o = 0; for (const p of parts) { all.set(p, o); o += p.length; }
  return `data:image/png;base64,${Buffer.from(all).toString('base64')}`;
}
